package com.automationstudio.engine.karate.gateway;
import static org.junit.jupiter.api.Assertions.*;import java.net.*;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import org.junit.jupiter.api.Test;
class KarateGatewayMainTest{
 @Test void authorizesOriginAndDnsBeforeRequestingSecret()throws Exception{AtomicInteger materializations=new AtomicInteger();var otherRequest=new GatewayTransport.Request("GET","https://other.example/api",Map.of(),new byte[0]);var denied=new GatewayTargetPolicy("https://example.com",GatewayTargetPolicy.AddressPolicy.GLOBAL_ONLY,h->new InetAddress[]{InetAddress.getByName("93.184.216.34")});assertThrows(GatewayTargetPolicy.GatewayFailure.class,()->KarateGatewayMain.authorize(denied,(t,r)->{materializations.incrementAndGet();return null;},otherRequest));assertEquals(0,materializations.get());var dnsDenied=new GatewayTargetPolicy("https://example.com",GatewayTargetPolicy.AddressPolicy.GLOBAL_ONLY,h->new InetAddress[]{InetAddress.getLoopbackAddress()});var admittedRequest=new GatewayTransport.Request("GET","https://example.com/api",Map.of(),new byte[0]);assertThrows(GatewayTargetPolicy.GatewayFailure.class,()->KarateGatewayMain.authorize(dnsDenied,(t,r)->{materializations.incrementAndGet();return null;},admittedRequest));assertEquals(0,materializations.get());var permitted=new GatewayTargetPolicy("https://example.com",GatewayTargetPolicy.AddressPolicy.GLOBAL_ONLY,h->new InetAddress[]{InetAddress.getByName("93.184.216.34")});assertNull(KarateGatewayMain.authorize(permitted,(t,r)->{materializations.incrementAndGet();return null;},admittedRequest));assertEquals(1,materializations.get());}
}
